<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import PageHeader from "@/components/PageHeader.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { useAuthSession } from "@/composables/useAuthSession";
import { ApiError } from "@/services/http";
import { listBuildingOptions, listElevators, saveElevator, toggleElevator, type BuildingOption, type Elevator } from "@/services/infrastructure";

const items = ref<Elevator[]>([]); const buildings = ref<BuildingOption[]>([]); const search = ref(""); const estado = ref<"all" | "active" | "inactive">("all"); const page = ref(1); const pageSize = 10; const pagination = ref({ page: 1, pageSize, total: 0, totalPages: 0 }); const loading = ref(false); const saving = ref(false); const error = ref(""); const success = ref(""); const formError = ref(""); const editing = ref<Elevator | null>(null); const showForm = ref(false); const confirmTarget = ref<Elevator | null>(null); const form = ref({ idEdificio: 0, codigoElevador: "", nombreElevador: "", cantidadPisos: null as number | null, codigoSistemaExterno: "" });
const auth = useAuthSession(); const canManage = computed(() => auth.user.value?.permissions.includes("ELEVADORES_ADMINISTRAR") ?? false);
const message = (value: unknown) => value instanceof ApiError ? value.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listElevators(search.value, page.value, pageSize, estado.value); items.value = result.items; pagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
async function loadBuildings() { try { buildings.value = (await listBuildingOptions()).items; } catch (cause) { error.value = message(cause); } }
function edit(item: Elevator | null) { if (!canManage.value) return; editing.value = item; formError.value = ""; form.value = { idEdificio: item?.idEdificio ?? buildings.value.find((option) => option.estadoEdificio)?.idEdificio ?? 0, codigoElevador: item?.codigoElevador ?? "", nombreElevador: item?.nombreElevador ?? "", cantidadPisos: item?.cantidadPisos ?? null, codigoSistemaExterno: item?.codigoSistemaExterno ?? "" }; showForm.value = true; }
async function save() { if (!canManage.value) return; formError.value = ""; saving.value = true; try { const creating = !editing.value; await saveElevator(editing.value?.idElevador ?? null, { ...form.value, codigoSistemaExterno: form.value.codigoSistemaExterno || null, ...(editing.value ? { usuarioActualizacion: "backoffice" } : { usuarioRegistro: "backoffice" }) }); showForm.value = false; success.value = creating ? "Elevador creado correctamente." : "Elevador actualizado correctamente."; await load(); } catch (cause) { formError.value = message(cause); } finally { saving.value = false; } }
function askToggle(item: Elevator) { if (canManage.value) confirmTarget.value = item; } async function toggle() { const target = confirmTarget.value; if (!target || !canManage.value) return; confirmTarget.value = null; try { await toggleElevator(target.idElevador, !target.estadoElevador); await load(); } catch (cause) { error.value = message(cause); } }
function changePage(nextPage: number) { page.value = nextPage; void load(); } watch([search, estado], () => { page.value = 1; void load(); }); onMounted(() => { void Promise.all([load(), loadBuildings()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración', to: '/' }, { label: 'Accesos' }, { label: 'Elevadores' }]" />
  <PageHeader eyebrow="Accesos / Infraestructura" title="Elevadores" description="Administración de elevadores asociados a edificios." :action-label="canManage ? 'Nuevo elevador' : undefined" @action="edit(null)" />
  <p v-if="!canManage" class="bo-form-note">Consulta de solo lectura. Para crear, editar o cambiar el estado se requiere el permiso ELEVADORES_ADMINISTRAR.</p>
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar por código o nombre..." aria-label="Buscar elevadores" /><select v-model="estado" aria-label="Filtrar por estado"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando elevadores...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay elevadores registrados.</strong><span>Ajuste la búsqueda{{ canManage ? ' o cree un nuevo elevador.' : '.' }}</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Código</th><th>Elevador</th><th>Edificio</th><th>Pisos</th><th>Estado</th><th v-if="canManage">Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idElevador"><td><strong>{{ item.codigoElevador }}</strong></td><td>{{ item.nombreElevador }}</td><td>{{ item.nombreEdificio }}</td><td>{{ item.cantidadPisos ?? "-" }}</td><td><StatusBadge :active="item.estadoElevador" /></td><td v-if="canManage"><div class="bo-actions"><button class="bo-action" @click="edit(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoElevador }" @click="askToggle(item)">{{ item.estadoElevador ? "Desactivar" : "Activar" }}</button></div></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} registros · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1" @click="changePage(page - 1)">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages" @click="changePage(page + 1)">Siguiente</button></div></footer></section>
  <div v-if="showForm && canManage" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ editing ? "Editar registro" : "Nuevo registro" }}</span><h2>{{ editing ? "Editar elevador" : "Crear elevador" }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><form class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Edificio *<select v-model.number="form.idEdificio" required><option :value="0" disabled>Seleccione...</option><option v-for="building in buildings.filter(item => item.estadoEdificio || item.idEdificio === form.idEdificio)" :key="building.idEdificio" :value="building.idEdificio">{{ building.codigoEdificio }} · {{ building.nombreEdificio }}</option></select></label><label>Código *<input v-model="form.codigoElevador" maxlength="30" required /></label><label>Nombre *<input v-model="form.nombreElevador" maxlength="150" required /></label><label>Cantidad de pisos<input v-model.number="form.cantidadPisos" type="number" min="-32768" max="32767" /></label><label>Código sistema externo<input v-model="form.codigoSistemaExterno" maxlength="100" /></label></div><p v-if="formError" class="bo-form-error">{{ formError }}</p><footer><button class="bo-btn" type="button" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? "Guardando..." : "Guardar" }}</button></footer></form></section></div>
  <ConfirmDialog :open="Boolean(confirmTarget) && canManage" title="Cambiar estado del elevador" :message="confirmTarget ? `¿Desea ${confirmTarget.estadoElevador ? 'desactivar' : 'activar'} este elevador? Esta acción puede revertirse posteriormente.` : ''" :confirm-label="confirmTarget?.estadoElevador ? 'Desactivar' : 'Activar'" @confirm="toggle" @cancel="confirmTarget = null" />
</template>
